  "intro": "**这一章的地基是一句话**：\n**只有定子通电 → 定子产生旋转磁场 → 转子被磁场\"感应\"出电流 → 转子被拖着同向转，\n但永远追不上磁场（追上就没有切割、没有电流、没有力了）—— 这就是\"异步\"两个字的来历。**\n\n25 道题里有一半可以用下面这几个数直接判：\n\n| 要背的数 | 值 |\n|---|---|\n| **直接起动电流** | 额定电流的 **4~7 倍** |\n| **380V 电动机的绝缘电阻**（500V 兆欧表） | **>0.5MΩ** |\n| **Y / △ 联结的分界** | **3kW 及以下用 Y，4kW 及以上用 △** |\n| **胶壳开关（开启式负荷开关）能直接起动的电动机** | **5.5kW 以下** |\n| **同步转速** | **n₁ = 60f / p**（50Hz 时：一对极 3000、两对极 1500、三对极 1000 r/min） |",
  "table": "| 项目 | 正确内容 |\n|---|---|\n| **工作原理** | **只有定子通电**；转子电流是**感应**来的；转子**与磁场同向**转、**转速略低**（异步） |\n| **定子 / 转子** | 定子**不动**（产生旋转磁场），转子**转动**（输出机械功率） |\n| **定子绕组** | 三相**对称**，空间互差 **120° 电角度** |\n| **转子铁芯** | **斜槽**（削弱谐波、降噪、避免起动死点） |\n| **同步转速** | **n₁ = 60f / p**；50Hz：**3000 / 1500 / 1000 / 750 r/min** |\n| **转差率** | **s = (n₁ − n) / n₁**；起动时 s=1，额定时 s≈0.01~0.06 |\n| **转子电流频率** | **f₂ = s · f₁**；**起动瞬间最高（≈50Hz）** |\n| **改变转向** | **对调任意两根相线** |\n| **直接起动电流** | 额定电流的 **4~7 倍** |\n| **最大转矩** | 与负载**无关**；**与电源电压的平方成正比（T ∝ U²）** |\n| **Y / △ 分界** | **3kW 及以下用 Y；4kW 及以上用 △** |\n| **Y-△ 起动** | 起动电流和转矩都降为**直接起动的 1/3**；**只适用于正常运行为 △ 的电机** |\n| **手动开关带电机** | **组合开关 / 胶壳开关只能直接起动 5.5kW 以下**，且不宜频繁 |\n| **频敏变阻器** | **只能用于绕线式**；起动**平滑但转矩不大**，**适合轻载**；靠 f₂ 下降自动减阻 |\n| **变极调速** | **只能用于笼型**（多速电机）；绕线式靠**转子串电阻**调速 |\n| **单相电机** | 用**单相电源**；**体积大、功率因数低、效率低、过载能力差**；**自己起动不了**，靠电容分相或罩极 |\n| **绝缘电阻** | 380V 电机用 **500V 兆欧表**测，**>0.5MΩ** 才可使用 |\n| **短路（堵转）试验** | 堵住转子、**加低电压**（约额定的 15%~25%）；空载试验是**加额定电压空转** |\n| **查轴承** | **断电后用手盘车**，绝不能通电转 |\n| **异响** | 正常是**均匀轻微的嗡嗡声**；**沉闷无力＝缺相**（最要命） |\n| **焦臭味** | **绕组过热、绝缘烧损**，立即停机；跟转速无关 |\n| **三种保护** | 短路→**熔断器/断路器**；过载→**热继电器**；来电自起动→**失压保护（自锁触头）** |",
