    "key": "六道题，一条铁律 + 一张保护清单。\n\n**铁律：电动机出现任何异常，先切断电源，找出原因之前不许再通电。**\n\n| 现象 | 处理 |\n|---|---|\n| **异常发响发热 + 转速急速下降** | **立即切断电源**，停机检查（多半是**堵转、缺相、过载**） |\n| **闻到焦臭味** | 停机后**必须找出原因才能再通电** —— 焦味说明绝缘已经烧了 |\n| **异音（尖叫、沉闷、摩擦、撞击、振动）** | **立即断电检查** |\n| **绝缘电阻不合格** | **不允许通电运行**，先干燥处理 |\n| 检修后 | 各项检查合格才能做**空载试验和短路试验** |\n\n**电动机电路的完整保护：短路、过载、欠压、断相** —— 四样，缺一样都算不完整。",
