  "intro": "**这一章看着杂（配电制式、防雷、绝缘材料、导线连接、电缆全塞在一起），\n但每一块都有一两个必背的数字或颜色。先把两张\"一眼就要认出来\"的表放在最前面：**\n\n**① 线色（★ 现场天天用，考试年年考）**\n\n| 线 | 颜色 |\n|---|---|\n| **A 相（L1）** | **黄** |\n| **B 相（L2）** | **绿** |\n| **C 相（L3）** | **红** |\n| **零线（N，工作零线）** | **淡蓝** |\n| **保护地线（PE）** | **绿/黄双色** |\n\n**口诀：黄绿红、蓝零、双色地。**\n\n**② 低压配电系统（第一个字母＝电源中性点接不接地，第二个字母＝设备外壳怎么接）**\n\n| 系统 | 电源中性点 | 设备外壳 | 特点 |\n|---|---|---|---|\n| **TN-C** | 接地 | 接 **PEN 线**（N 与 PE **全程合一**） | 最省线，但保护差 |\n| **TN-C-S** | 接地 | **前段合一（PEN），从某点起分开成 N + PE** | 现在最常用 |\n| **TN-S** | 接地 | **N 和 PE 全程分开**（三相五线制） | 最安全 |\n| **TT** | 接地 | **各自单独接地**（不接零） | 农村、临时用电常见 |\n| **IT** | **不接地**（或经阻抗接地） | **接地（保护接地）** | 用于矿井、医院手术室等 |",
  "table": "| 项目 | 正确内容 |\n|---|---|\n| **线色** | **A 黄 / B 绿 / C 红 / N 淡蓝 / PE 绿黄双色** |\n| **TN-C / TN-S / TN-C-S** | **C=合一、S=分开**；TN-C-S 是**先合后分**，分开后不许再并 |\n| **IT 系统** | 电源中性点**不接地**，设备**保护接地**（不是接零） |\n| **爆炸危险场所** | **三相五线制、单相三线制**（必须有专用 PE） |\n| **雷电分类** | **直击雷 / 感应雷 / 雷电侵入波**（另有球雷）；**沿线路来的冲击波不是直击雷** |\n| **接闪杆规格** | 针长 1m 以下：圆钢 ≥12mm、钢管 ≥20mm；**1~2m：圆钢 ≥16mm、钢管 ≥25mm** |\n| **引下线** | 三项要求：**机械强度、耐腐蚀、热稳定**；**不得少于两根** |\n| **避雷器检查** | **每年雷雨季节前**测绝缘电阻（2500V 兆欧表），跟上一年比、明显下降就停电检查 |\n| **绝缘材料** | **没有绝对不导电的**；绝缘老化是**物理+化学+电+机械**共同作用 |\n| **导线工作电压** | **≤ 额定电压**（一切\"工作值 ≤ 额定值\"） |\n| **允许工作温度** | 橡皮 **65℃**、**聚氯乙烯 70℃**、交联聚乙烯 **90℃**（不是统一 50℃） |\n| **导线截面过小** | **会因发热引发火灾**；电气火灾主因还有短路、过载、**接触不良**、漏电 |\n| **线路按用电性质分** | **动力线路 / 照明线路** |\n| **铜线铝线** | **严禁直接连接**（电化学腐蚀），须用**铜铝过渡接头** |\n| **导线接头三要求** | 接触电阻**不大于同长度导线**；机械强度**不低于原导线 90%**；绝缘**不低于原绝缘** |\n| **接头位置** | **避开绝缘子固定处和受力点**；不许留在管内、墙内 |\n| **松线** | **严禁突然剪断**，须用紧线器缓慢放松 |\n| **电缆外护层代号** | **前一位＝铠装层，后一位＝外被层**（如 VV22） |\n| **电缆隧道照明** | **必须用安全电压（≤36V，特别潮湿 12V）** |\n| **电缆保护管内径** | **≥ 电缆外径的 1.5 倍**；穿管导线总截面 **≤ 管内截面的 40%** |",
