  "intro": "**这一章是全书唯一\"真的能救命\"的一章，也是最值得逐条背熟的一章。**\n主线有三条：\n\n**① 触电为什么会死** —— 电流大小、时间长短、路径、频率，\n核心数字：**感知 1mA、摆脱 10mA、致命 30mA 以上、工频最危险。**\n**② 救人的顺序** —— **脱离电源 → 就地抢救 → 边救边送医**，\n**三个动作的顺序错一个都可能白救。**\n**③ 灭火** —— **先断电，对准火焰根部，电气火灾用不导电的灭火剂。**",
